        private String name;
        private String loreText;
        private String requiredMod;
        public Item item;

        public Entry(ResourceLocation id, Rarity rarity, ItemConfig.Item config, String lore, boolean fireproof) {
            this.id = id;
            this.rarity = rarity;
            this.config = config;
            this.lore = lore;
            this.fireproof = fireproof;
        }

