            return this;
        }

        public Entry loreText(String loreText) {
            this.loreText = loreText;
            return this;
        }

        public Entry requiredMod(String modId) {
            this.requiredMod = modId;
            return this;
        }

        public String requiredMod() {
            return this.requiredMod;
        }

        public String translatedName() {
            if (this.name != null) {
                return this.name;
            }
            String[] words = this.id.getPath().split("_");
            StringBuilder builder = new StringBuilder();
            for (String word : words) {
                if (!builder.isEmpty()) {
                    builder.append(" ");
                }
                builder.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
            }
            return builder.toString();
        }

        public String translatedLore() {
            return this.loreText != null ? this.loreText : "";
        }

        public boolean fireproof() {
            return this.fireproof;
        }

        public Item create(Item.Properties settings, ItemAttributeModifiers attributes) {
            String slot = this.id.getPath().contains("ring") ? "ring" : (this.id.getPath().contains("necklace") ? "necklace" : null);
            this.item = AdditionalJewelryFactory.getFactory().apply(new AdditionalJewelryFactory.ItemArgs(settings, attributes, this.lore, slot));
            return this.item;
        }

        public Item item() {
            return this.item;
        }

        public Entry setTier(int tier) {
            this.tier = tier;
            this.fireproof = tier >= 3;
            return this;
        }

        public int tier() {
            return this.tier;
        }
    }
