    public static ConfigManager<FeaturesConfig> featuresConfig = new ConfigManager("features", (Object)new FeaturesConfig()).builder().setDirectory("jewelry").sanitize(true).build();

    public static void init() {
        itemConfig.refresh();
        villageConfig.refresh();
        featuresConfig.refresh();
        if (!Platform.util().isModLoaded("lithostitched")) {
            StructurePoolAPI.injectAll((StructurePoolConfig)((StructurePoolConfig)JewelryMod.villageConfig.value));
