    private static Armor.ItemSettingsTweaker commonSettings(ResourceLocation equipmentSetId) {
        return Armors.commonSettings(equipmentSetId, 0);
    }

    private static Armor.ItemSettingsTweaker commonSettings(ResourceLocation equipmentSetId, int glyphSlots) {
        return Armor.ItemSettingsTweaker.standard(itemSettings -> {
            itemSettings.component(SpellDataComponents.EQUIPMENT_SET, (Object)equipmentSetId).component(DataComponents.RARITY, (Object)Rarity.RARE);
            if (glyphSlots > 0) {
                itemSettings.component(WitcherDataComponents.GLYPH_SLOTS, (Object)new GlyphSlots(glyphSlots, List.of()));
            }
        });
    }

    public static Holder<ArmorMaterial> material(String name, int protectionHead, int protectionChest, int protectionLegs, int protectionFeet, int enchantability, Holder<SoundEvent> equipSound, Supplier<Ingredient> repairIngredient) {
        ArmorMaterial material = new ArmorMaterial(Map.of(ArmorItem.Type.HELMET, protectionHead, ArmorItem.Type.CHESTPLATE, protectionChest, ArmorItem.Type.LEGGINGS, protectionLegs, ArmorItem.Type.BOOTS, protectionFeet), enchantability, equipSound, repairIngredient, List.of(new ArmorMaterial.Layer(ResourceLocation.fromNamespaceAndPath((String)"witcher_rpg", (String)name))), 0.0f, 0.0f);
        return Registry.registerForHolder((Registry)BuiltInRegistries.ARMOR_MATERIAL, (ResourceLocation)ResourceLocation.fromNamespaceAndPath((String)"witcher_rpg", (String)name), (Object)material);
    }

    private static Armor.Entry create(Holder<ArmorMaterial> material, ResourceLocation id, int durability, Armor.Set.ItemFactory factory, ArmorSetConfig defaults, int tier, Armor.ItemSettingsTweaker settings) {
        Armor.Entry entry = Armor.Entry.create(material, (ResourceLocation)id, (int)durability, (Armor.Set.ItemFactory)factory, (ArmorSetConfig)defaults, (Equipment.LootProperties)Equipment.LootProperties.of((int)tier), (Armor.ItemSettingsTweaker)settings);
        entries.add(entry);
        return entry;
    }

    public static void register(Map<String, ArmorSetConfig> configs) {
        Armor.register(configs, entries, WitcherGroup.WITCHER_KEY);
    }
}

