        return Armor.ItemSettingsTweaker.standard(itemSettings -> itemSettings.component(SpellDataComponents.EQUIPMENT_SET, (Object)equipmentSetId).component(DataComponents.RARITY, (Object)Rarity.RARE));
    }

    private static ArmorSetConfig pieces(int head, int chest, int legs, int feet, UnaryOperator<ArmorSetConfig.Piece> modifiers) {
        return ArmorSetConfig.with((ArmorSetConfig.Piece)((ArmorSetConfig.Piece)modifiers.apply(new ArmorSetConfig.Piece(head))), (ArmorSetConfig.Piece)((ArmorSetConfig.Piece)modifiers.apply(new ArmorSetConfig.Piece(chest))), (ArmorSetConfig.Piece)((ArmorSetConfig.Piece)modifiers.apply(new ArmorSetConfig.Piece(legs))), (ArmorSetConfig.Piece)((ArmorSetConfig.Piece)modifiers.apply(new ArmorSetConfig.Piece(feet))));
    }

