        ((ICuriosItemHandler)inventory.get()).getCurios().forEach((slotType, stacksHandler) -> {
            IDynamicStackHandler slotStacks = stacksHandler.getStacks();
            for (int i = 0; i < slotStacks.getSlots(); ++i) {
                ItemStack stack = slotStacks.getStackInSlot(i);
                if (stack.isEmpty()) continue;
                stacks.add(stack);
            }
        });
        return stacks;
    }

    public static List<ItemStack> getEquippedStacks(Player player) {
        Optional inventory = CuriosApi.getCuriosInventory((LivingEntity)player);
        if (inventory.isEmpty()) {
            return List.of();
        }
        ArrayList<ItemStack> equipped = new ArrayList<ItemStack>();
        ((ICuriosItemHandler)inventory.get()).getCurios().forEach((slotType, stacksHandler) -> {
            IDynamicStackHandler slotStacks = stacksHandler.getStacks();
            for (int i = 0; i < slotStacks.getSlots(); ++i) {
                ItemStack stack = slotStacks.getStackInSlot(i);
                if (stack.isEmpty()) continue;
                if (slotType.equals(SLOT_SPELL_BOOK)) {
                    equipped.addFirst(stack);
                    continue;
                }
                equipped.add(stack);
            }
        });
        return equipped;
    }
}

