import net.spell_engine.api.spell.registry.SpellRegistry;
import net.spell_engine.client.SpellEngineClient;
import org.jetbrains.annotations.Nullable;

public class ScrollItem
extends Item {
    public static final ResourceLocation ID = ResourceLocation.fromNamespaceAndPath((String)"spell_engine", (String)"spell_scroll");

    public ScrollItem(Item.Properties settings) {
        super(settings);
    }

    public boolean isEnchantable(ItemStack stack) {
        return false;
    }

    public static void applySpell(ItemStack itemStack, Holder<Spell> spellEntry, @Nullable TagKey<Spell> pool) {
        itemStack.set(SpellDataComponents.SPELL_CONTAINER, (Object)SpellContainers.forScroll(spellEntry));
        ScrollItem.onSpellAdded(itemStack, spellEntry, pool);
    }

    public static String translationKeyForPool(ResourceLocation poolId) {
        return "item." + poolId.getNamespace() + "." + poolId.getPath();
    }

    public static ResourceLocation modelIdForPool(ResourceLocation poolId) {
        return ResourceLocation.fromNamespaceAndPath((String)poolId.getNamespace(), (String)("item/" + poolId.getPath()));
    }

    public static void onSpellAdded(ItemStack itemStack, Holder<Spell> spellEntry, @Nullable TagKey<Spell> pool) {
        Spell spell = (Spell)spellEntry.value();
        int ordinal = Math.max(spell.tier - 1, 0);
        Rarity rarity = Rarity.values().length > ordinal ? Rarity.values()[ordinal] : Rarity.EPIC;
        itemStack.set(DataComponents.RARITY, (Object)rarity);
        if (pool != null) {
            ResourceLocation modelId = ScrollItem.modelIdForPool(pool.location());
            itemStack.set(SpellDataComponents.ITEM_MODEL, (Object)modelId);
            String key = ScrollItem.translationKeyForPool(pool.location());
            if (Language.getInstance().has(key)) {
                itemStack.set(DataComponents.ITEM_NAME, (Object)Component.translatable((String)key));
            }
        }
    }

    @Nullable
    public static TagKey<Spell> resolveSpellPool(Level world, Holder<Spell> spellEntry) {
        Optional wrapper = world.registryAccess().lookup(SpellRegistry.KEY);
        if (wrapper.isPresent()) {
            return ScrollItem.resolveSpellPool((HolderLookup<Spell>)((HolderLookup)wrapper.get()), spellEntry);
        }
        return null;
    }

    @Nullable
    public static TagKey<Spell> resolveSpellPool(HolderLookup<Spell> wrapper, Holder<Spell> spellEntry) {
        Optional<HolderSet.Named> tag = wrapper.listTags().filter(t -> ((TagKey)t.unwrapKey().get()).location().getPath().startsWith("spell_scroll/") && t.contains(spellEntry)).findFirst();
        if (tag.isPresent()) {
            return (TagKey)tag.get().unwrapKey().get();
        }
        return null;
    }

    public void appendHoverText(ItemStack stack, Item.TooltipContext context, List<Component> tooltip, TooltipFlag type) {
        if (SpellEngineClient.config.showSpellBindingTooltip) {
            tooltip.add((Component)Component.translatable((String)"item.spell_engine.scroll.table_hint").withStyle(ChatFormatting.GRAY));
        }
    }
}
